<?php
/*
 * Printable Pattern of Life report (Controller_Persons::action_pattern_of_life_report).
 * Variables: $meta (person / generated by / at), $a (Helpers_PatternOfLife::analyse),
 * $at (Helpers_PatternOfLife::at_time or NULL), $hash (SHA-256, also in the audit log).
 * Standalone page: no site template, no external resources.
 */
$h  = function ($s) { return HTML::chars((string) $s); };
$d  = function ($s) { return $s ? date('d M Y', strtotime($s)) : ''; };
$dt = function ($s) { return $s ? date('d M Y H:i', strtotime($s)) : ''; };
$pn = function ($p) {
    if (!empty($p['address'])) return $p['address'];
    return ($p['lat'] !== NULL) ? $p['lat'] . ', ' . $p['lng'] : $p['key'];
};
$f    = $a['filters'];
$days = array('Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun');
$ref  = strtoupper(substr($hash, 0, 16));
$max  = 0;
foreach ($a['grid'] as $row) { foreach ($row as $n) { $max = max($max, $n); } }
?><!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Pattern of Life Report <?php echo $h($ref); ?></title>
<style>
    @page { size: A4; margin: 14mm 12mm 16mm; }
    * { box-sizing: border-box; }
    body { font: 12px/1.45 "Segoe UI", Arial, sans-serif; color: #111; margin: 0; background: #e9ecef; }
    .sheet { max-width: 210mm; margin: 16px auto; background: #fff; padding: 14mm 12mm; box-shadow: 0 1px 4px rgba(0,0,0,.15); }
    .toolbar { max-width: 210mm; margin: 16px auto 0; display: flex; gap: 8px; justify-content: flex-end; }
    .toolbar button { font: inherit; padding: 6px 14px; border: 1px solid #3c8dbc; background: #3c8dbc; color: #fff; border-radius: 3px; cursor: pointer; }
    .toolbar button.secondary { background: #fff; color: #3c8dbc; }
    .classification { text-align: center; font-weight: 700; letter-spacing: 2px; color: #b00; border: 2px solid #b00; padding: 3px; margin-bottom: 10px; }
    .head { display: flex; justify-content: space-between; align-items: flex-end; border-bottom: 2px solid #111; padding-bottom: 6px; margin-bottom: 10px; }
    .head .org { font-size: 11px; color: #444; text-transform: uppercase; letter-spacing: .5px; }
    .head h1 { font-size: 20px; margin: 2px 0 0; }
    .head .ref { text-align: right; font-size: 11px; }
    .head .ref strong { font-size: 13px; font-family: Consolas, monospace; }
    h2 { font-size: 14px; margin: 16px 0 6px; padding-bottom: 3px; border-bottom: 1px solid #bbb; page-break-after: avoid; }
    table { width: 100%; border-collapse: collapse; margin-bottom: 6px; }
    th, td { border: 1px solid #ccc; padding: 3px 5px; text-align: left; vertical-align: top; }
    th { background: #f2f2f2; font-weight: 600; }
    table.meta th { width: 26%; }
    tr { page-break-inside: avoid; }
    .num { text-align: right; white-space: nowrap; }
    .finding { border-left: 4px solid #3c8dbc; background: #f5f9fc; padding: 6px 9px; margin: 6px 0; }
    .finding.incident { border-left-color: #b00; background: #fdf3f3; }
    .tiles { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
    .tile { border: 1px solid #ccc; padding: 6px 8px; }
    .tile .lbl { font-size: 10px; text-transform: uppercase; color: #555; }
    .tile .val { font-weight: 600; }
    .grid td { width: 3.6%; height: 14px; padding: 0; border-color: #e3e3e3; }
    .grid th { font-weight: 400; font-size: 9px; padding: 1px; text-align: center; background: #fff; border-color: #e3e3e3; }
    ul.anoms { margin: 0; padding-left: 18px; }
    ul.anoms li { margin: 2px 0; }
    .tag { display: inline-block; font-size: 9px; padding: 0 4px; border: 1px solid #888; border-radius: 2px; margin-left: 4px; text-transform: uppercase; }
    .method { font-size: 10.5px; color: #333; }
    .method li { margin: 2px 0; }
    .integrity { font-size: 10px; border: 1px dashed #888; padding: 6px 8px; margin-top: 12px; word-break: break-all; }
    .sign { display: grid; grid-template-columns: 1fr 1fr; gap: 30px; margin-top: 26px; font-size: 11px; }
    .sign div { border-top: 1px solid #111; padding-top: 3px; }
    .muted { color: #666; }
    @media print {
        body { background: #fff; }
        .toolbar { display: none; }
        .sheet { margin: 0; padding: 0; box-shadow: none; max-width: none; }
        th { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
        .grid td, .finding, .classification { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    }
</style>
</head>
<body>
<div class="toolbar">
    <button type="button" class="secondary" onclick="window.close()">Close</button>
    <button type="button" onclick="window.print()">Print / Save as PDF</button>
</div>
<div class="sheet">
    <div class="classification">RESTRICTED — FOR OFFICIAL USE ONLY</div>
    <div class="head">
        <div>
            <div class="org">Counter Terrorism Department, Khyber Pakhtunkhwa · DRAMS</div>
            <h1>Pattern of Life Report</h1>
        </div>
        <div class="ref">Report reference<br><strong><?php echo $h($ref); ?></strong></div>
    </div>

    <table class="meta">
        <tr><th>Person</th><td><?php echo $h($meta['person_name']); ?> <span class="muted">(DRAMS person #<?php echo (int) $meta['person_id']; ?>)</span></td></tr>
        <tr><th>CNIC</th><td><?php echo $h($meta['person_cnic'] !== '' ? $meta['person_cnic'] : '—'); ?></td></tr>
        <tr><th>Mobile number(s) analysed</th><td><?php echo $h($f['phone'] !== '' ? $f['phone'] : 'All numbers in the person\'s CDRs'); ?></td></tr>
        <tr><th>Period analysed</th><td><?php echo $h($d($f['from']) . ' – ' . $d($f['to'])); ?></td></tr>
        <tr><th>Records</th><td><?php echo (int) $a['totals']['calls']; ?> calls, <?php echo (int) $a['totals']['sms']; ?> SMS on <?php echo (int) $a['totals']['days_active']; ?> active day(s); <?php echo (int) $a['totals']['with_place']; ?> with a tower, <?php echo (int) $a['totals']['on_map']; ?> with coordinates</td></tr>
        <tr><th>Generated by</th><td><?php echo $h($meta['generated_by']); ?> <span class="muted">(user #<?php echo (int) $meta['user_id']; ?>)</span></td></tr>
        <tr><th>Generated at</th><td><?php echo $h($dt($meta['generated_at'])); ?> (PKT)</td></tr>
    </table>

    <?php if ($at): ?>
        <h2>Incident check — where was the person at <?php echo $h($dt($at['query']['at'])); ?>?</h2>
        <div class="finding incident"><?php echo $h($at['summary']); ?></div>
        <?php if ($at['query']['site']): ?>
            <p class="muted">Incident site: <?php echo $h($at['query']['site']['lat'] . ', ' . $at['query']['site']['lng']); ?>. Window: ±<?php echo (int) $at['query']['window']; ?> min.</p>
        <?php else: ?>
            <p class="muted">Window: ±<?php echo (int) $at['query']['window']; ?> min. No incident site given, so no distances.</p>
        <?php endif; ?>
        <?php
        $rows = $at['records'];
        if (!$rows) { $rows = array_values(array_filter(array($at['before'], $at['after']))); }
        ?>
        <?php if ($rows): ?>
            <table>
                <tr><th>Time</th><th>Offset</th><th>Type</th><th>Other party</th><th>Tower / place</th><th class="num">km from site</th><th class="num">km from home</th></tr>
                <?php foreach ($rows as $r):
                    $kmh = ($a['home'] !== NULL) ? Helpers_PatternOfLife::km($r, $a['home']) : NULL; ?>
                    <tr>
                        <td><?php echo $h($dt($r['t'])); ?></td>
                        <td class="num"><?php echo ($r['minutes'] > 0 ? '+' : '') . (int) $r['minutes']; ?> min</td>
                        <td><?php echo $h(strtoupper($r['kind']) . ' ' . ($r['outgoing'] ? 'out' : 'in') . ($r['kind'] === 'call' ? ' ' . $r['duration'] . 's' : '')); ?></td>
                        <td><?php echo $h($r['other']); ?></td>
                        <td><?php echo $h($r['address'] !== '' ? $r['address'] : ($r['lat'] !== NULL ? $r['lat'] . ', ' . $r['lng'] : '—')); ?></td>
                        <td class="num"><?php echo $r['km_site'] !== NULL ? $h($r['km_site']) : '—'; ?></td>
                        <td class="num"><?php echo $kmh !== NULL ? $h($kmh < 10 ? round($kmh, 1) : round($kmh)) : '—'; ?></td>
                    </tr>
                <?php endforeach; ?>
            </table>
        <?php endif; ?>
    <?php endif; ?>

    <h2>Summary</h2>
    <div class="tiles">
        <div class="tile"><div class="lbl">Likely home (night tower)</div>
            <div class="val"><?php echo $a['home'] ? $h($pn($a['home'])) : 'Not enough data'; ?></div>
            <?php if ($a['home']): ?><div class="muted"><?php echo (int) $a['home']['share']; ?>% of night activity · <?php echo (int) $a['home']['days']; ?> day(s)</div><?php endif; ?></div>
        <div class="tile"><div class="lbl">Likely work (weekday day tower)</div>
            <div class="val"><?php echo $a['work'] ? $h($pn($a['work'])) : 'Not enough data'; ?></div>
            <?php if ($a['work']): ?><div class="muted"><?php echo (int) $a['work']['share']; ?>% of working-hours activity · <?php echo (int) $a['work']['days']; ?> day(s)</div><?php endif; ?></div>
        <div class="tile"><div class="lbl">Most active hours</div>
            <div class="val"><?php
                $peak = array();
                foreach ($a['peak'] as $p) { $peak[] = sprintf('%02d:00', $p['hour']); }
                echo $peak ? $h(implode(', ', $peak)) : '—'; ?></div></div>
        <div class="tile"><div class="lbl">Handsets / SIMs in period</div>
            <div class="val"><?php echo count($a['devices']['imei']); ?> handset(s), <?php echo count($a['devices']['imsi']); ?> SIM(s)</div>
            <div class="muted">All time in CDRs: <?php echo (int) $a['devices_all_time']['imei']; ?> handset(s), <?php echo (int) $a['devices_all_time']['imsi']; ?> SIM(s)</div></div>
    </div>

    <h2>Anomalies (<?php echo count($a['anomalies']); ?>)</h2>
    <?php if ($a['anomalies']): ?>
        <ul class="anoms">
            <?php foreach ($a['anomalies'] as $x): ?><li><?php echo $h($x['text']); ?></li><?php endforeach; ?>
        </ul>
    <?php else: ?>
        <p class="muted">No anomalies in this period.</p>
    <?php endif; ?>

    <h2>Key places</h2>
    <?php if ($a['places']): ?>
        <table>
            <tr><th>#</th><th>Tower / place</th><th class="num">Calls+SMS</th><th class="num">Days</th><th class="num">Night</th><th class="num">Work hrs</th><th>First seen</th><th>Last seen</th></tr>
            <?php foreach (array_slice($a['places'], 0, 20) as $i => $p): ?>
                <tr>
                    <td><?php echo $i + 1; ?></td>
                    <td><?php echo $h($pn($p)); ?>
                        <?php if ($a['home'] && $p['key'] === $a['home']['key']): ?><span class="tag">Home</span><?php endif; ?>
                        <?php if ($a['work'] && $p['key'] === $a['work']['key']): ?><span class="tag">Work</span><?php endif; ?></td>
                    <td class="num"><?php echo (int) $p['n']; ?></td>
                    <td class="num"><?php echo (int) $p['days']; ?></td>
                    <td class="num"><?php echo (int) $p['night']; ?></td>
                    <td class="num"><?php echo (int) $p['work']; ?></td>
                    <td><?php echo $h($d($p['first'])); ?></td>
                    <td><?php echo $h($d($p['last'])); ?></td>
                </tr>
            <?php endforeach; ?>
        </table>
        <?php if (count($a['places']) > 20): ?><p class="muted">Top 20 of <?php echo count($a['places']); ?> places shown.</p><?php endif; ?>
    <?php else: ?>
        <p class="muted">No tower information in this period.</p>
    <?php endif; ?>

    <h2>When active (calls + SMS, hour × weekday)</h2>
    <table class="grid">
        <tr><th></th><?php for ($hr = 0; $hr < 24; $hr++): ?><th><?php echo $hr % 3 === 0 ? $hr : ''; ?></th><?php endfor; ?></tr>
        <?php foreach ($a['grid'] as $di => $row): ?>
            <tr><th><?php echo $days[$di]; ?></th>
                <?php foreach ($row as $n):
                    $alpha = ($n > 0 && $max > 0) ? round(0.12 + 0.88 * $n / $max, 2) : 0; ?>
                    <td style="background: rgba(60,141,188,<?php echo $alpha; ?>)" title="<?php echo (int) $n; ?>"></td>
                <?php endforeach; ?>
            </tr>
        <?php endforeach; ?>
    </table>

    <h2>Handsets and SIMs in this period</h2>
    <?php
    $devs = array();
    foreach ($a['devices']['imei'] as $x) { $devs[] = array('Handset (IMEI)', $x); }
    foreach ($a['devices']['imsi'] as $x) { $devs[] = array('SIM (IMSI)', $x); }
    ?>
    <?php if ($devs): ?>
        <table>
            <tr><th>Type</th><th>Number</th><th class="num">Records</th><th>First used</th><th>Last used</th></tr>
            <?php foreach ($devs as $x): ?>
                <tr><td><?php echo $h($x[0]); ?></td><td><?php echo $h($x[1]['id']); ?></td><td class="num"><?php echo (int) $x[1]['n']; ?></td>
                    <td><?php echo $h($d($x[1]['first'])); ?></td><td><?php echo $h($d($x[1]['last'])); ?></td></tr>
            <?php endforeach; ?>
        </table>
    <?php else: ?>
        <p class="muted">No IMEI / IMSI in this period.</p>
    <?php endif; ?>

    <h2>Method and limitations</h2>
    <ul class="method">
        <li>Source: call and SMS detail records (CDRs) held in DRAMS for this person. Locations are the serving cell towers recorded by the operator, not GPS positions; a tower can cover several kilometres.</li>
        <li>"Likely home" is the tower used most between 22:00 and 06:00; "likely work" is the tower used most Monday–Friday 09:00–17:00 (at least <?php echo Helpers_PatternOfLife::MIN_ANCHOR_EVENTS; ?> records needed). Both are indications for further enquiry, not proof of residence or employment.</li>
        <li>Anomalies: silent periods of <?php echo Helpers_PatternOfLife::SILENT_DAYS; ?>+ days without records; days with more than three standard deviations above the normal daily volume; handsets / SIMs first used after the period began; towers <?php echo Helpers_PatternOfLife::TRAVEL_KM; ?>+ km from the home tower.</li>
        <li>A silent period can also mean CDRs were not obtained for those days. Towers without coordinates from the operator are listed but distances to them cannot be measured.</li>
        <li>Generated automatically by DRAMS from the records available at the time of generation.</li>
    </ul>

    <div class="integrity">
        <strong>Integrity:</strong> SHA-256 <?php echo $h($hash); ?><br>
        This value was recorded in the DRAMS audit log when the report was generated. A copy whose reference does not match the log entry for this person, user and time has been altered or was not produced by DRAMS.
    </div>

    <div class="sign">
        <div>Prepared by (name, rank, signature)</div>
        <div>Verified by (name, rank, signature)</div>
    </div>
    <div class="classification" style="margin-top:14px">RESTRICTED — FOR OFFICIAL USE ONLY</div>
</div>
</body>
</html>
